[AifCollectionTypeAttribute('return', Types::Class, classStr(FMVehicleDataContract))]
public List RetrieveAvailableVehicles()
{
    List result = new List(Types::Class);
    FMVehicleDataContract vehicle;
    FMVehicle bufferVehicle;
    FMVehicleModel modelrecord;


    while select * from bufferVehicle where FMVehicleStatus::Available == bufferVehicle.Status
    {            
        vehicle = new FMVehicleDataContract();
        vehicle.Make(bufferVehicle.Description);
        vehicle.VIN(bufferVehicle.VIN);

        select firstonly *  from modelrecord where modelrecord.RecId == bufferVehicle.VehicleModel;

        vehicle.Model(modelrecord.Model);

        result.addEnd(vehicle);            
    }

    return result;
}
